insert into public.recipes (id, status, cover_image, prep_minutes, cook_minutes, servings, video_url, family_id, variant_label, variant_image, related_post_ids) values ('recipe-mizeria', 'published', 'https://kdrbtwwhmzszzukcffsu.supabase.co/storage/v1/object/public/recipe-media/recipes/recipe-mizeria/6f3ac245-1a4c-47cb-a36b-27f86d7d25c1.webp', 20, 0, 4, null, null, '{}'::jsonb, '', array['post-sonntagsessen', 'post-smietana-schmand', 'post-wielkanoc', 'post-panieren']::text[]) on conflict (id) do update set status = excluded.status, cover_image = excluded.cover_image, prep_minutes = excluded.prep_minutes, cook_minutes = excluded.cook_minutes, servings = excluded.servings, video_url = excluded.video_url, family_id = excluded.family_id, variant_label = excluded.variant_label, variant_image = excluded.variant_image, related_post_ids = excluded.related_post_ids, updated_at = now();
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-mizeria', 'de', 'Mizeria', 'mizeria', 'Ganz dünn gehobelte Gurken ziehen unter Salz ihren Saft, dann verbindet kalte Śmietana mit frischem Dill alles zu einer kühlen, erfrischenden Beilage für Schabowy und den Sonntagstisch.', '[{"text":"Gurken waschen, in sehr dünne Scheiben hobeln oder schneiden, leicht salzen und 10 bis 15 Minuten Saft ziehen lassen.","tip":"Salz entzieht der Gurke Wasser, sonst verdünnt der austretende Saft später die Śmietana. Wie sich das mit dem fertigen Teller verbindet, zeigt der [Panieren-Guide](/de/blog/panieren-schabowy) für Schabowy."},{"text":"Gurken leicht ausdrücken oder abgießen. Mit [Śmietana oder Schmand](/de/blog/smietana-schmand), gehacktem Dill, einer Prise Zucker und Pfeffer vermengen."},{"text":"Zum Schluss abschmecken, denn Säure und Salz kommen erst jetzt dazu. Wer mag, reibt noch etwas Zwiebel sehr fein hinein.","tip":"Mische den Salat nicht zu früh an, wenn Gäste erst später kommen, sonst wird er wässrig und verliert seinen Biss."},{"text":"Kalt servieren zu [Kotlet schabowy](/de/rezepte/kotlet-schabowy), Kartoffeln oder als Oster-Beilage nach dem [Wielkanoc-Speiseplan](/de/blog/wielkanoc-speiseplan).","tip":"Ein Buffetsalat mit Mayonnaise und Gemüse ist ein ganz anderes Gericht, das findest du unter [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa)."}]'::jsonb, 'Mizeria, kühl, cremig-säuerlich, nach Dill und frischer Gurke. Der Name Mizeria kommt vom lateinischen und französischen Wort für Elend, misère, und das ist eine Art Ironie: Sprachforscher wie Aleksander Brückner ordnen ihn dem Wortfeld für Armut zu, weil Gurken einst genau in der kargen Vorsommerzeit reiften, wenn sonst kaum Gemüse verfügbar war, und arme Landfamilien oft nur diesen einen schlichten Salat auf dem Tisch hatten. Die bekanntere Legende, dass Königin Bona Sforza vor Heimweh nach Italien weinte, wenn sie polnische Gurken aß, gilt unter Historikern als hübsche, aber unbelegte Geschichte. Ursprünglich wurde die Gurke nicht nur mit Sahne, sondern auch mit Milch, Essig und reichlich Zucker angemacht, teils sogar kurz mit heißem Wasser überbrüht, wie es Kochbücher des 19. Jahrhunderts festhalten. Erst mit der Zeit setzte sich sure Śmietana als die polnische Variante durch und machte aus dem kargen Elend-Essen einen festen Bestandteil des Sonntagstischs, oft neben knusprigem [Kotlet schabowy](/de/rezepte/kotlet-schabowy). Mit einer kalten Suppe wie [Chłodnik](/de/rezepte/chlodnik-litewski) hat Mizeria trotz ähnlicher Zutaten nichts zu tun, denn sie bleibt Salat, keine Suppe.

## Einkaufen und kochen

Feste Salat- oder Feldgurken, frischer Dill und ein Milchprodukt mit klarer Rolle, Schmand oder saure Sahne statt irgendeiner Sahne aus dem Kühlregal. Welche Stufe wohin passt, erklärt der [Śmietana-und-Schmand-Guide](/de/blog/smietana-schmand), dort findest du auch Alternativen, während hier der Anwendungsfall Mizeria im Mittelpunkt steht. Zucker und Pfeffer sparsam dosieren, optional etwas sehr fein geriebene Zwiebel. Einkaufstag und Spezialitäten dazu liefert der [Polenladen-Guide](/de/blog/polenladen-einkaufen).

Die Gurke dünn hobeln, salzen und warten lassen, dann ausdrücken, denn genau diese Reihenfolge entscheidet über die Konsistenz. Śmietana kalt unterheben, nicht schlagen, sonst gerinnt sie leicht. Dill kommt erst am Ende dazu, damit er frisch bleibt und sein Aroma nicht verkocht. Zucker gleicht die natürliche Bitterkeit mancher Gurken aus, er soll den Salat nicht süß wie ein Dessert machen. Abschmecken lohnt sich erst kurz vor dem Servieren, weil die Gurke währenddessen weiter Wasser abgibt.

In deutschen Küchen geht Mizeria oft schneller als gedacht: Gurken aus dem Supermarkt, Schmand aus dem Kühlregal, Dill vom Kräutertopf auf der Fensterbank. Wer den Sonntag durchplant, mischt Mizeria erst nach dem Braten an, parallel zum [Panieren-Ablauf](/de/blog/panieren-schabowy) für den Schabowy, damit sie nicht zu lange wässrig zieht. Den größeren Menü-Rahmen ohne Küchenchaos liefert das [polnische Sonntagsessen](/de/blog/sonntagsessen-polnisch).

## Am Tisch

Klassisch neben [Kotlet schabowy](/de/rezepte/kotlet-schabowy) und Kartoffeln, ebenso gut zu [Kotlet mielony](/de/rezepte/kotlet-mielony). Im Festmenü taucht sie als kühle Beilage im [Wielkanoc-Speiseplan](/de/blog/wielkanoc-speiseplan) auf. Am Alltagstisch reicht eine Schüssel für vier Personen, dabei lieber kurz vor dem Essen nachlegen, als den Salat lange wässrig stehen zu lassen. Reste halten sich einen Tag im Kühlschrank, sollten aber erneut abgeschmeckt und mit frischem Dill ergänzt werden.

Wer die Gurken nicht aussalzt, bekommt eine wässrige Sauce statt einer cremigen Beilage. Heiße oder zu kalte Śmietana direkt aus dem Kühlschrank kann sich leicht trennen. Zu viel Zwiebel überdeckt den Dill komplett. Mizeria mit dem kalten Chłodnik zu verwechseln oder sie als Basis für kalte Suppen misszuverstehen, führt ebenfalls in die falsche Richtung. Für ein Buffet sollte man den Salat erst kurz vorher anmischen, sonst wird er bis zum Servieren zu weich.

Mit Joghurt wird die Beilage leichter, mit etwas Zitronensaft säuerlicher, und wenn die Gurken schon süß sind, kann der Zucker ganz entfallen. Manche Familien geben eine Spur Knoblauch dazu, das ist dann ehrlich als Hausvariante zu benennen und nicht als Standardrezept. Warm serviert ist es keine Mizeria mehr. Ein festlicher Buffetsalat mit Mayonnaise und Gemüse hat einen ganz anderen Charakter und heißt [Sałatka jarzynowa](/de/rezepte/salatka-jarzynowa). Die verwandte kühle Linie im Sommer bleibt der Chłodnik, der als eigenes Rezept weiterlebt.', 'Mizeria Rezept | Gurkensalat mit Śmietana | Alemniam', 'Mizeria, polnischer Gurkensalat mit Śmietana und Dill. Beilage zu Schabowy, bilingual mit DE-Einkauf.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
insert into public.recipe_translations (recipe_id, locale, title, slug, excerpt, steps, article, seo_title, seo_description) values ('recipe-mizeria', 'pl', 'Mizeria', 'mizeria', 'Cienko pokrojone ogórki puszczają sok pod solą, a potem zimna śmietana ze świeżym koperkiem zamienia je w chłodny, orzeźwiający dodatek do schabowego i niedzielnego stołu.', '[{"text":"Ogórki umyj, pokrój lub zetrzyj w bardzo cienkie plasterki, lekko posól i odstaw na 10 do 15 minut, żeby puściły sok.","tip":"Sól odciąga z ogórka wodę, inaczej sok później rozrzedzi śmietanę. Jak to się łączy z gotowym talerzem, pokazuje [przewodnik panierowania](/pl/blog/panierowanie-kotlet) schabowego."},{"text":"Lekko odciśnij lub odlej sok. Wymieszaj z [śmietaną lub Schmandem](/pl/blog/smietana-czy-schmand), siekanym koperkiem, szczyptą cukru i pieprzem."},{"text":"Dopraw na końcu, bo kwas i sól dodajesz dopiero teraz. Kto lubi, wciera jeszcze bardzo drobno startą cebulę.","tip":"Nie mieszaj sałatki za wcześnie, jeśli goście przyjdą później, bo zrobi się wodnista i straci chrupkość."},{"text":"Podawaj zimną do [kotleta schabowego](/pl/rezepte/kotlet-schabowy), ziemniaków albo jako dodatek wielkanocny według [menu wielkanocnego](/pl/blog/menu-wielkanocne).","tip":"Sałatka bufetowa z majonezem i warzywami to zupełnie inne danie, znajdziesz je jako [sałatka jarzynowa](/pl/rezepte/salatka-jarzynowa)."}]'::jsonb, 'Mizeria, chłodna, kremowo-kwaśna, z koperkiem i świeżym ogórkiem. Nazwa mizeria pochodzi od łacińskiego i francuskiego słowa oznaczającego nędzę, misère, i to jest pewna ironia: językoznawcy, jak Aleksander Brückner, wiążą ją z ubóstwem, bo ogórki dojrzewały właśnie w chudym okresie przedletnim, gdy innych warzyw brakowało, a biedne rodziny na wsi miały na stole często tylko tę jedną prostą sałatkę. Popularna legenda, jakoby królowa Bona Sforza płakała z tęsknoty za Italią przy jedzeniu polskich ogórków, uchodzi wśród historyków za ładną, ale niepotwierdzoną opowieść. Pierwotnie ogórki mieszano nie tylko ze śmietaną, ale i z mlekiem, octem oraz sporą ilością cukru, a czasem nawet krótko parzono wrzątkiem, co potwierdzają XIX-wieczne książki kucharskie. Dopiero z czasem kwaśna śmietana stała się polską wersją klasyczną i zmieniła dawne biedne danie w stały punkt niedzielnego stołu, często obok chrupiącego [kotleta schabowego](/pl/rezepte/kotlet-schabowy). Z chłodną zupą jak [chłodnik](/pl/rezepte/chlodnik-litewski) mizeria mimo podobnych składników nie ma nic wspólnego, bo zostaje sałatką, nie zupą.

## Zakupy i gotowanie

Jędrne ogórki sałatkowe lub gruntowe, świeży koperek i nabiał z jasną rolą, Schmand albo kwaśna śmietana zamiast byle jakiej śmietany z chłodni. Który produkt do czego pasuje, wyjaśnia [przewodnik śmietana albo Schmand](/pl/blog/smietana-czy-schmand), tam znajdziesz też alternatywy, a tu zostaje samo zastosowanie w mizerii. Cukier i pieprz dawkuj oszczędnie, opcjonalnie dodaj bardzo drobno startą cebulę. W [przewodniku po sklepie polskim](/pl/blog/sklep-polski-zakupy) kupisz typowe specjały do tego dania.

Ogórek kroić cienko, solić i odczekać, potem odcisnąć, bo właśnie ta kolejność decyduje o konsystencji. Śmietanę mieszać na zimno, nie ubijać, bo łatwo się zważy. Koperek dodawaj dopiero na końcu, żeby zachował świeżość aromatu. Cukier łagodzi naturalną goryczkę niektórych ogórków, ale sałatka nie ma smakować jak deser. Doprawiać warto dopiero tuż przed podaniem, bo ogórek cały czas oddaje wodę.

W niemieckich kuchniach mizeria powstaje często szybciej, niż się wydaje: ogórki z supermarketu, Schmand z chłodni, koperek z doniczki na parapecie. Kto planuje całą niedzielę, miesza mizerię dopiero po usmażeniu mięsa, równolegle do [panierowania](/pl/blog/panierowanie-kotlet) schabowego, żeby nie stała za długo wodnista. Szerszy kontekst menu bez chaosu w kuchni daje [obiad niedzielny](/pl/blog/obiad-niedzielny).

## Przy stole

Klasycznie obok [kotleta schabowego](/pl/rezepte/kotlet-schabowy) i ziemniaków, równie dobrze pasuje do [kotleta mielonego](/pl/rezepte/kotlet-mielony). Na święta pojawia się jako chłodny dodatek w [menu wielkanocnym](/pl/blog/menu-wielkanocne). Na co dzień jedna miska wystarcza na cztery osoby, lepiej dokładać porcje tuż przed jedzeniem, niż trzymać całość długo wodnistą. Resztki wytrzymują dzień w lodówce, ale warto je ponownie doprawić i dosypać świeżego koperku.

Brak odsączenia ogórków daje wodnisty sos zamiast kremowego dodatku. Zbyt zimna śmietana prosto z lodówki albo za gorące otoczenie może się rozdzielić. Za dużo cebuli całkowicie zagłusza koperek. Mylenie mizerii z zimnym chłodnikiem albo traktowanie jej jako bazy do zimnych zup też prowadzi na manowce. Na bufet lepiej mieszać sałatkę tuż przed podaniem, bo inaczej zdąży zmięknąć.

Z jogurtem sałatka robi się lżejsza, z cytryną bardziej kwaśna, a jeśli ogórki są już słodkie, cukier można całkiem pominąć. Niektóre rodziny dodają odrobinę czosnku, ale to warto uczciwie nazwać wariantem domowym, nie standardem. Podana na ciepło przestaje być mizerią. Odświętna sałatka bufetowa z majonezem i warzywami ma zupełnie inny charakter i nazywa się [sałatka jarzynowa](/pl/rezepte/salatka-jarzynowa). Pokrewna chłodna linia latem to chłodnik, który zostaje osobnym przepisem.', 'Mizeria przepis | Sałatka z ogórków | Alemniam', 'Mizeria, ogórki ze śmietaną i koperkiem. Dodatek do schabowego, dwujęzycznie z zakupami w DE.') on conflict (recipe_id, locale) do update set title = excluded.title, slug = excluded.slug, excerpt = excluded.excerpt, steps = excluded.steps, article = excluded.article, seo_title = excluded.seo_title, seo_description = excluded.seo_description;
